export function translateText(sourceText, targetLang) {
  if (!sourceText || targetLang === 'FR') return sourceText;
  
  const trimmed = sourceText.trim();
  if (trimmed.length < 2) return sourceText;
  
  // 1. Exact match
  if (MASTER_PHRASES[trimmed] && MASTER_PHRASES[trimmed][targetLang]) {
    const leadSpace = sourceText.match(/^\s*/)[0];
    const trailSpace = sourceText.match(/\s*$/)[0];
    return leadSpace + MASTER_PHRASES[trimmed][targetLang] + trailSpace;
  }
  
  // 2. Case-insensitive match
  const lower = trimmed.toLowerCase();
  for (const [key, tr] of Object.entries(MASTER_PHRASES)) {
    if (key.toLowerCase() === lower && tr[targetLang]) {
      const leadSpace = sourceText.match(/^\s*/)[0];
      const trailSpace = sourceText.match(/\s*$/)[0];
      let translated = tr[targetLang];
      if (trimmed === trimmed.toUpperCase() && trimmed.length > 2) {
        translated = translated.toUpperCase();
      }
      return leadSpace + translated + trailSpace;
    }
  }
  
  // 3. Prefix matching (#01 • ..., 01. ..., PAR ...)
  if (trimmed.startsWith('#') && trimmed.includes('•')) {
    const parts = trimmed.split('•');
    const prefix = parts[0].trim();
    const rest = parts.slice(1).join('•').trim();
    const restTr = translateText(rest, targetLang);
    return prefix + ' • ' + restTr;
  }
  
  if (/^\d{2}\.\s+/.test(trimmed)) {
    const match = trimmed.match(/^(\d{2}\.\s+)(.*)$/);
    if (match) {
      return match[1] + translateText(match[2], targetLang);
    }
  }

  if (trimmed.toLowerCase().startsWith('par ')) {
    const rest = trimmed.substring(4).trim();
    const byMap = { EN: 'By', SW: 'Na', ES: 'Por', PT: 'Por', DE: 'Von', IT: 'Di', AR: 'بقلم' };
    return (byMap[targetLang] || 'By') + ' ' + rest;
  }

  return sourceText;
}
